package pe.vichaval.gestionriego.caja.repository;import java.math.BigDecimal;import java.time.LocalDate;import java.util.List;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import pe.vichaval.gestionriego.caja.entity.Egreso;public interface EgresoRepository extends JpaRepository<Egreso,Long>{boolean existsByComprobanteIgnoreCase(String c);List<Egreso>findAllByOrderByFechaDescIdDesc();@Query("select coalesce(sum(e.monto),0) from Egreso e where e.fecha=:f and e.estado='REGISTRADO'")BigDecimal totalFecha(@Param("f")LocalDate f);}
